"""Entrega de 46, bloque 3, después de leer los índices 0–1145 completos."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[5]
sys.path.insert(0, str(ROOT / 'scripts'))
from construir import validate_fact

ROWS = json.loads((ROOT / 'campanas/xoltacan/revision/borradores/46/bloque_3_segmentos.json').read_text(encoding='utf-8'))
SOURCE = ROOT / 'campanas/xoltacan/fuentes/46 - yRdWu0NIldc.es-orig.vtt'
facts = []


def fact(number, title, statement, start, end, cue_start, entities, limitation='', kind='hecho_confirmado'):
    cue = next(row for row in ROWS if row['inicio'] == cue_start)
    row = dict(id=f'46-{number}', titulo=title, tipo=kind, afirmacion=statement,
               inicio=start, fin=end, cita=cue['texto_original'],
               evidencia_cue=dict(inicio=cue['inicio'], fin=cue['fin'], texto=cue['texto_original']),
               entidades=entities, ambito='salida de la aldea y reencuentros en Iktan',
               conocedores=[], conocimiento_personaje='desconocido',
               nota_conocimiento='Acceso de Madame Oghma sin establecer en este pasaje.',
               confianza='lectura de subtítulos; audio no cotejado', limitacion=limitation)
    validate_fact(row, SOURCE)
    facts.append(row)


fact(201, 'Citlali se recupera drenando al último tiranosaurio',
     'Después del rayo que ha derribado a un dinosaurio y dejado aturdido al otro, Citlali se acerca furiosa al superviviente y le pone la mano encima. Unos destellos recorren sus tatuajes mientras ella deja de sentirse tan herida. El director confirma que los dos dinosaurios quedan muertos en el suelo; Citlali todavía sigue dolorida por los mordiscos.',
     '01:38:56.280', '01:40:32.310', '01:40:06.080', ['Citlali', 'Tiranosaurios de la aldea caníbal'],
     'La recuperación tras el drenaje no equivale a desaparición de la maldición, ausencia de heridas o curación completa. Uno de los dinosaurios ya había caído antes de este turno.')
fact(202, 'Eleanor corta carne del dinosaurio sin herramientas adecuadas',
     'Eleanor quiere llevarse comida y abre el vientre de un tiranosaurio con la espada. El director le explica que así no puede despellejarlo ni hacer cortes precisos; acaba permitiendo que se lleve un trozo destrozado, mezclado con otras partes, difícil de preparar. Ione insiste en que deben marcharse porque teme que el olor de la carne atraiga a más animales.',
     '01:40:32.320', '01:42:36.310', '01:42:07.960', ['Eleanor', 'Ione', 'Tiranosaurios de la aldea caníbal'],
     'No obtiene una piel íntegra ni raciones cocinadas. La llegada de nuevos depredadores es un riesgo que expresa el personaje, no un segundo ataque ocurrido ya.')
fact(203, 'Ione reprocha a Zoltan el daño eléctrico y le da libertad de marcharse',
     'Ione llama chispitas a Zoltan y le reprocha haber electrocutado a quienes lo liberaron de las cadenas. Él responde que pretendía impedir que el lagarto la devorase. Mientras se lava la sangre y la ropa en el agua, Ione le dice que ya es libre y puede seguir su camino; ella y los demás se disponen a salir de la aldea.',
     '01:42:39.239', '01:44:35.870', '01:42:45.480', ['Ione', 'Zoltan', 'Citlali'],
     'La discusión no acredita una traición deliberada de Zoltan ni que llegue a abandonar al grupo. Chispitas es un apodo contextual de este personaje.')
fact(204, 'La extracción del colmillo termina en una descarga descontrolada',
     'Zoltan intenta arrancar un colmillo del tiranosaurio usando lo que llama cirugía eléctrica. Tras una salvación de sabiduría, la mano se ilumina mucho más de lo esperado y la descarga chamusca todo el cadáver. Quedan huesos visibles y dientes ennegrecidos y rotos. Zoltan reconoce que todavía no controla bien su poder.',
     '01:44:38.320', '01:46:59.910', '01:46:23.599', ['Zoltan', 'Tiranosaurios de la aldea caníbal'],
     'El intento no entrega un colmillo intacto como botín. No se convierte este descontrol en una capacidad de precisión dominada o disponible sin límites.')
fact(205, 'Zoltan sostiene a Citlali y Eleanor le proporciona una montura temporal',
     'Zoltan se acerca a Citlali, que camina despacio por las heridas, le ofrece el hombro y la sujeta por la cintura para ayudarla. Ione les reprocha después no ser de su tripulación y ofrece tratar como amigos a quienes se unan, propuesta que recibe una negativa. Eleanor dibuja runas, clava la espada e invoca un caballo de duración corregida a diez minutos. Citlali lo monta para descansar de los mordiscos.',
     '01:47:03.270', '01:49:25.229', '01:48:53.480', ['Zoltan', 'Citlali', 'Eleanor', 'Ione', 'Tripulación del Zampaolas'],
     'La ayuda física y la montura no curan la maldición ni establecen una relación amorosa. Las bromas sobre Nox muerto tres días no fijan por sí solas un calendario absoluto ni anulan el duelo de Citlali. No se afirma que el caballo dure todo el viaje.')
fact(206, 'La investigación de Zoltan provoca pequeños fuegos sin hallar botín',
     'Mientras Citlali sube al caballo, Zoltan examina las casas de la aldea donde había estado encerrado para ver si encuentra algo que llevarse. La investigación no obtiene un hallazgo. Las chispas que salen de él prenden pequeños fuegos y decide apartarse y seguir a los compañeros.',
     '01:49:25.239', '01:50:32.070', '01:50:18.920', ['Zoltan', 'Aldea caníbal de la cascada'],
     'La narración comienza con una broma sobre quemar toda la aldea y después precisa pequeños fuegos. No declarar una destrucción total ni añadir objetos encontrados.')
fact(207, 'Citlali reconoce el camino y el grupo llega a Iktan',
     'Ione empieza a avanzar sin saber orientarse. Tras nuevas tiradas, Citlali reconoce caminos de la jungla y sitúa Cuicapalli a varios días hacia el este; recuerda que al norte pueden alcanzar el lago próximo a Iktan. Indica la ruta y el grupo la sigue. El viaje se elide con una improvisación humorística y la siguiente escena efectiva muestra la llegada a Iktan, con plantas coloridas, cabañas de madera y guardias sorprendidos por tantos visitantes.',
     '01:50:32.080', '01:55:59.629', '01:54:30.719', ['Citlali', 'Ione', 'Eleanor', 'Zoltan', 'Iktan', 'Cuicapalli'],
     'Los templos, dios infernal, río de pirañas y Pecio mencionados en el montaje se presentan como invención jocosa de la elipsis y no generan aventuras, muertes o fichas revisadas. No se fijan días exactos ni coordenadas del recorrido.')
fact(208, 'Ione encuentra a la tripulación en la taberna de Iktan',
     'Ione ve un cartel de cerveza y se dirige rápidamente a la taberna buscando a sus compañeros. Encuentran a Baps, Mugre, Ojo Ausente y los trillizos jugando a cartas y bebiendo, además de Sir Poncelot, Ilikar, Erandy y Lunaria en la barra. Ione pregunta si están bien y le responden que llevan cuatro días allí. Aliviada, se sienta y bebe una cerveza.',
     '01:56:01.320', '01:58:52.510', '01:58:03.760', ['Ione', 'Baps', 'Mugre', 'Ojo Ausente', 'Tripulación del Zampaolas', 'Sir Poncelot', 'Ilikar', 'Erandy', 'Lunaria', 'El Huevo Emplumado', 'Iktan'],
     'Los cuatro días son la duración referida por los presentes, no un calendario completo de la campaña. La localización de estos compañeros no demuestra que hayan regresado todos los tripulantes ni permite representar conversaciones extensas de jugadores ausentes.')
fact(209, 'Citlali encuentra a Etley con Leo a la salida del colegio',
     'Citlali intenta advertir que los extranjeros deben comportarse con cuidado en Iktan, pero sus compañeros se dispersan antes de escucharla. Al dirigirse hacia el templo, ve salir a Leo con Etley y lo llama con un silbido. Aparece la profesora Miausi con gafas, pide a Leo que no la obligue a hablar otra vez con su madre y explica que intenta confundir al otro pequeño. Citlali identifica a Etley como su hijo y lo hace sentarse con otro silbido.',
     '01:58:52.520', '02:01:13.149', '02:00:20.599', ['Citlali', 'Etley', 'Leo', 'Miausi', 'Colegio de Iktan'],
     'Miausi se presenta como profesora; no se la identifica automáticamente con la directora del capítulo 45 solo por tener gafas. Etley sigue siendo la cría de dinosaurio, no un nuevo niño por asistir al colegio.')
fact(210, 'Miausi invita a Citlali a la reunión de madres',
     'Miausi cuenta que unos muchachos, uno muy grande y otro bajo y calvo, llevaron a Etley. Después invita a Citlali a la reunión de madres que celebran los domingos. Le advierte de que otra asistente, la princesa leonina de Atlan, suele utilizar lenguaje soez, y se disculpa de antemano por ella. Citlali responde que sabrá cómo tratar a alguien así.',
     '02:00:55.719', '02:02:00.510', '02:01:20.079', ['Miausi', 'Citlali', 'Etley', 'Naór', 'Colegio de Iktan'],
     'La descripción de quienes llevaron a la cría no aporta sus nombres en este diálogo. La invitación no significa que la reunión ya se celebre, ni confirma una identidad institucional entre colegio y academia de guerreros.', 'declaracion_personaje')
fact(211, 'Citlali reprende a Leo y se lleva a Etley',
     'Leo amenaza con pedir a su madre que golpee a la profesora y sigue insultando. Citlali se acerca, lo golpea con la alpargata y le exige que controle el lenguaje. El niño protesta invocando a la princesa de Atlan como su madre, recibe otro golpe y sale llorando a buscarla. Citlali advierte a Etley que no imite esas expresiones; Miausi reitera la cita del domingo y vuelve a clase.',
     '02:02:00.520', '02:03:44.669', '02:02:55.159', ['Citlali', 'Leo', 'Etley', 'Miausi', 'Naór', 'Colegio de Iktan'],
     'El niño llama madre a Naór dentro del vínculo de cuidado ya establecido; la escena no prueba parentesco biológico. No se narra que llegue a encontrarla, que se pierda definitivamente o que Tesara reciba una reprimenda.')
fact(212, 'Zoltan toma una cerveza y Angelique lo corteja',
     'Zoltan pide una cerveza en la taberna. La encargada felina le pregunta por el dinero, se presenta como Angelic y también ofrece que la llame princesa. Le propone una habitación y bebe a su lado, apartando a Sir Poncelot de la barra. Más adelante lo acaricia y le ofrece mostrarle otros rituales en privado.',
     '02:03:44.679', '02:12:35.910', '02:04:50.280', ['Zoltan', 'Angelique', 'Sir Poncelot', 'El Huevo Emplumado'],
     'Se vincula la presentación con Angelique de la taberna de Iktan, manteniendo la grafía provisional. Princesa forma parte del coqueteo y no demuestra un título nobiliario. El comentario comparativo con Coyote no significa que este participe en la escena.')
fact(213, 'Eleanor comprueba que Erandy está en la taberna',
     'Eleanor se concentra en comprobar que Erandy se encuentra bien y se reúne con ella. Cerca están Ilikar jugando con Cipo y Lunaria, a quien el director imagina intentando quemar algún trozo de madera. Eleanor expresa que también quiere coger a Lunaria en brazos; el director advierte que esta no se dejaría.',
     '02:05:47.159', '02:06:48.350', '02:06:18.239', ['Eleanor', 'Erandy', 'Ilikar', 'Cipo', 'Lunaria', 'El Huevo Emplumado'],
     'La llegada y la preocupación de Eleanor no demuestran una curación completa del agotamiento anterior de Erandy. El intento incendiario de Lunaria se expresa de forma conjetural y no acredita otro incendio consumado; tampoco se ejecuta un abrazo forzado a Lunaria.')
fact(214, 'Ione descubre la ausencia del novato llamado Jacki',
     'Baps confirma que han alquilado habitaciones, aunque están llenas y se duerme en común. Ione revisa a los tripulantes y echa de menos al novato, al que los demás llaman Jacki. Nadie confirma su destino; unos especulan con muerte o tiburones, mientras los trillizos dicen que ya no estaba cuando salieron de la playa. Ione teme que se haya perdido en la jungla y no quiere perder a otro hombre.',
     '02:06:48.360', '02:09:03.229', '02:08:23.679', ['Ione', 'Baps', 'Tripulación del Zampaolas', 'Novato ausente de Ione', 'El Huevo Emplumado'],
     'La mención se mantiene provisional sin identificarla automáticamente con Jack veterano ni con el Jackie cautivo referido por Taylor. Las conjeturas no prueban muerte, captura, devoración o localización actual.', 'declaracion_personaje')
fact(215, 'Ione propone recaudar recursos y reunir apoyos para recuperar Shiaru',
     'Ione anuncia a la tripulación que intentará vender una joya para obtener dinero y después hablar con la gente nueva para sumar apoyos a su causa, recuperar Shiaru y averiguar si el novato ha regresado por allí. Sus hombres describen con extrañeza las costumbres de Iktan. Al recordar a Bonnie, Ione admite que ya no está y trata de tranquilizarlos prometiendo que ella seguirá protegiéndolos.',
     '02:09:03.239', '02:11:24.390', '02:09:29.480', ['Ione', 'Bonnie', 'Tripulación del Zampaolas', 'Novato ausente de Ione', 'Shiaru', 'Iktan'],
     'Son planes de financiación y reclutamiento, sin una operación ejecutada para recuperar Shiaru. Las noticias de los tripulantes sobre una elfa pálida y una estatua móvil no identifican por sí solas cada persona ni resuelven todos los riesgos de Iktan.', 'declaracion_personaje')
fact(216, 'Citlali explica a Ione el drenaje como parte de su maldición',
     'Ione se cruza con Citlali y Etley y reconoce a la cría al recordar el huevo. Pide acompañarlas porque quiere preguntar por lo ocurrido al dinosaurio. Citlali explica que la luz y el drenaje forman parte de una maldición, recuerda que descubrió ese efecto con Patata y acepta llevar a Ione ante Walulu, a quien esta cree capaz de aclarar el significado de los tatuajes.',
     '02:13:10.440', '02:15:37.629', '02:14:11.639', ['Ione', 'Citlali', 'Etley', 'Patata', 'Walulu'],
     'La explicación identifica el fenómeno como Citlali lo entiende, sin revelar origen, cura o significado de las marcas. La visita a Walulu solo se propone: no se representa una audiencia ni un análisis de los tatuajes.', 'declaracion_personaje')
fact(217, 'La búsqueda de comprador separa a Ione de Citlali',
     'Ione muestra la joya de oro que quiere vender y pregunta a Citlali dónde hacerlo. Ella no conoce bien las tiendas y le aconseja preguntar o mirar los carteles. Una intervención del chat resta catorce monedas de oro a Citlali. Ione busca un comercio reconocible y entra en una tienda con productos de alquimia, mientras Citlali se queda fuera con Etley.',
     '02:15:37.639', '02:18:13.870', '02:16:29.599', ['Ione', 'Citlali', 'Etley', 'Froger', 'Collar hallado por Ione en la aldea caníbal', 'Iktan'],
     'La pérdida de oro se atribuye al chat y no identifica un ladrón en la ciudad. Citlali no acompaña a Ione dentro de la tienda ni llega por ello a Walulu.')
fact(218, 'Froger compra el collar a Ione por veinticuatro monedas',
     'Ione se presenta ante un alquimista con aspecto de sapo y le ofrece su collar de oro y joyas para reunir recursos. Él propone veinticinco monedas de oro. Ione pide veintiséis, pero el comerciante baja su oferta a veinticuatro y ella acepta; el director le indica que sume esa cantidad y nombra a Froger.',
     '02:17:24.120', '02:19:39.950', '02:19:24.639', ['Ione', 'Froger', 'Collar hallado por Ione en la aldea caníbal', 'Iktan'],
     'La venta queda resuelta por veinticuatro, aunque el montaje final aún la describa negociando. El collar no se identifica con el de Blink o el antiguo encargo de Bonnie ni recibe poderes mágicos por tener joyas.')
fact(219, 'Citlali intenta enseñar buenos modales a Etley',
     'Mientras Ione negocia, Citlali habla con Etley y le insiste en que sea un buen pollito y no imite las malas palabras de Leo. La cría se distrae con una mariposa. El director recuerda al cierre que lleva gorro y mochila del colegio, aunque sigue siendo un animal que no entiende por qué está allí.',
     '02:19:39.960', '02:23:46.110', '02:20:09.200', ['Citlali', 'Etley', 'Leo', 'Colegio de Iktan'],
     'La intención educativa de Citlali no prueba que Etley aprenda a hablar, comprenda las explicaciones o pase a ser un niño humano.')
fact(220, 'Eleanor vende los objetos que llevaba',
     'Eleanor decide desprenderse de los objetos acumulados para no seguir cargándolos. El director la dirige a un herrero y establece que se vendan a la mitad de su valor. La transacción se resuelve mediante el inventario mientras continúa la escena de los demás, y el cierre la presenta terminando de vender sus joyas y otras pertenencias.',
     '02:20:18.479', '02:23:34.030', '02:21:07.040', ['Eleanor', 'Iktan'],
     'Los números sueltos y el cálculo que se traslada al chat no permiten fijar aquí un total literal fiable. No se identifica a este herrero con Armin de Shiaru o el de Cuicapalli.')
fact(221, 'Zoltan y Angelique se retiran a una habitación',
     'Tras el coqueteo en la barra, Angelique toma del brazo a Zoltan y lo lleva a una habitación, cuya puerta cierra. Una carta del chat le concede furia y el final representa el encuentro privado mediante ruidos y chispas que salen de la puerta. Los otros permanecen en la taberna; Citlali sigue hablando con Etley e Ione termina su venta a Froger.',
     '02:21:14.359', '02:24:20.520', '02:21:52.399', ['Zoltan', 'Angelique', 'El Huevo Emplumado', 'Citlali', 'Etley', 'Ione', 'Froger'],
     'El cierre no narra consecuencias posteriores, una nueva descarga contra el pueblo o un vínculo matrimonial. La anécdota sobre Gur de Kuroto pertenece a la conversación de mesa y no incorpora ese personaje ni sus hechos a Xoltacan.')

stages = [
    dict(titulo='El último dinosaurio y las chispas', texto='Citlali se acerca al tiranosaurio que queda con vida y le pone la mano encima. Los destellos recorren sus tatuajes mientras recupera fuerzas; el director confirma que los dos animales caen muertos. Eleanor intenta llevarse carne, pero su espada solo le permite cortar un trozo mal preparado y los demás quieren salir antes de atraer nuevos depredadores. Ione reprocha a Zoltan que haya electrocutado a quienes lo liberaron. Él sostiene que trataba de impedir que el dinosaurio la devorara. Aún cubierto de sangre, se lava y después intenta obtener un colmillo mediante su electricidad. El poder vuelve a desbordarse: chamusca el cadáver y ennegrece y rompe los dientes. El colmillo no llega a convertirse en botín. Zoltan admite que todavía no controla bien lo que le ocurre.', referencias=['46-201', '46-202', '46-203', '46-204']),
    dict(titulo='La ruta recuperada', texto='Citlali sigue dolorida por los mordiscos. Zoltan le ofrece el hombro para caminar y Eleanor invoca una montura que la lleva durante el breve tiempo que dura el conjuro. Antes de partir, Zoltan registra las casas de la aldea, sin hallar nada; las chispas prenden pequeños fuegos y lo convencen de marcharse. Ione intenta encabezar el camino, pero no sabe orientarse. Es Citlali quien acaba reconociendo los senderos y recuerda cómo alcanzar el lago próximo a Iktan. Los compañeros la siguen y el viaje queda elidido. Cuando vuelve la narración del recorrido llegan a la aldea de plantas coloridas y cabañas de madera. Ione encuentra un cartel de cerveza y corre hacia la taberna. Allí están sus tripulantes y los otros compañeros: le cuentan que llevan cuatro días esperándolos. La capitana se deja caer, aliviada, y toma una cerveza.', referencias=['46-205', '46-206', '46-207', '46-208']),
    dict(titulo='El colegio y el novato ausente', texto='Mientras los demás se dispersan, Citlali encuentra a Etley junto a Leo a la salida del colegio. La profesora Miausi se queja del comportamiento del niño y de su influencia sobre la cría. Citlali reconoce a Etley como suyo y recibe una invitación a la reunión de madres del domingo. Leo vuelve a insultar y amenazar; ella lo golpea con la alpargata y lo reprende. Él sale llorando a buscar a Naór, a quien llama mamá. Citlali se lleva a Etley y le pide que no imite esas palabras. En la taberna Eleanor se reúne con Erandy, mientras Ione pregunta por las habitaciones y revisa a su gente. Echa de menos al novato llamado Jacki: los compañeros no saben qué le ocurrió y solo pueden decir que ya faltaba al salir de la playa. Ione quiere conseguir dinero, reunir apoyos para recuperar Shiaru y averiguar si el ausente ha vuelto por allí. Ante el recuerdo de Bonnie, promete proteger a los suyos.', referencias=['46-209', '46-210', '46-211', '46-213', '46-214', '46-215']),
    dict(titulo='Las preguntas y el collar', texto='Ione se encuentra de nuevo con Citlali y reconoce a Etley como la criatura del huevo. Al preguntar por el dinosaurio, Citlali explica que el drenaje pertenece a su maldición y recuerda que lo descubrió con Patata. Plantean consultar a Walulu, pero la conversación queda en intención: Ione se distrae buscando dónde vender una joya y Citlali permanece con Etley. El comerciante al que llega es Froger, un alquimista con aspecto de sapo. Ofrece veinticinco monedas por el collar; Ione pide veintiséis y termina aceptando veinticuatro cuando él rebaja la oferta. Con esa pequeña recaudación avanza su plan de obtener recursos, todavía sin una alianza o expedición organizada para recuperar Shiaru. Eleanor también vende lo que llevaba, mientras Citlali insiste en educar a Etley, que atiende más a una mariposa que a sus consejos.', referencias=['46-216', '46-217', '46-218', '46-219', '46-220']),
    dict(titulo='El cierre en la taberna', texto='Zoltan permanece junto a Angelique, la encargada felina que lo ha recibido con una cerveza y un insistente coqueteo. Ella lo invita a una habitación y ambos se apartan tras cerrar la puerta. Una carta de furia y las chispas de Zoltan dan lugar a la última escena humorística mientras los demás siguen ocupados en la taberna y en sus ventas. El capítulo termina con el grupo ya reunido en Iktan, pero con el novato aún sin localizar, la visita a Walulu por hacer y los planes de Ione para Shiaru todavía pendientes.', referencias=['46-212', '46-221']),
]


def history(name, kind, title, text, references, new=False, description='', note=''):
    return dict(nombre=name, tipo=kind, nueva=new, descripcion=description, nota=note,
                etapas=[dict(titulo=title, texto=text, referencias=references)])


histories = [
    history('Citlali', 'personaje', 'El camino que vuelve a reconocer', 'Citlali drena al tiranosaurio superviviente y recupera parte de sus fuerzas, aunque sigue dolorida. Acepta ayuda para caminar y una montura temporal de Eleanor. Después reconoce los senderos que permiten llegar a Iktan. Allí recupera a Etley del colegio, reprende a Leo y se compromete a acudir a la reunión de madres. Explica a Ione que su drenaje forma parte de la maldición y plantea llevarla ante Walulu, sin llegar a esa audiencia.', ['46-201', '46-205', '46-207', '46-209', '46-210', '46-211', '46-216', '46-219']),
    history('Ione', 'personaje', 'Reunirse para volver a Shiaru', 'Ione discute con Zoltan por la descarga que alcanzó a sus rescatadores. Sigue después a Citlali hasta Iktan y encuentra a su gente en la taberna, donde llevan cuatro días. La alegría queda incompleta al descubrir que falta el novato llamado Jacki. Propone reunir dinero y nuevos apoyos para recuperar Shiaru y buscarlo. Vende un collar a Froger por veinticuatro monedas y habla con Citlali sobre la maldición, sin resolver todavía la visita a Walulu ni organizar la expedición.', ['46-203', '46-205', '46-207', '46-208', '46-214', '46-215', '46-216', '46-217', '46-218']),
    history('Eleanor', 'personaje', 'La montura y el reencuentro', 'Eleanor corta un trozo de carne del dinosaurio pese a no disponer de herramientas adecuadas y proporciona a Citlali un caballo temporal. Al llegar a Iktan comprueba que Erandy está en la taberna y se reúne con ella. Después vende los objetos que llevaba a la mitad del valor indicado por el director, sin que este tramo conserve un total fiable.', ['46-202', '46-205', '46-208', '46-213', '46-220']),
    history('Zoltan', 'personaje', 'El poder que todavía se desborda', 'Zoltan explica que quiso proteger a sus rescatadores, aunque Ione le reprocha la descarga. Al intentar extraer un colmillo, su poder chamusca el cadáver y rompe los dientes; al registrar las casas provoca pequeños fuegos. Ayuda a la herida Citlali y acompaña al grupo a Iktan. Allí pide una cerveza a Angelique, acepta su coqueteo y ambos se retiran a una habitación en el cierre.', ['46-203', '46-204', '46-205', '46-206', '46-207', '46-212', '46-221'], True, 'Hombre recién liberado que manifiesta descargas eléctricas de control incierto y acompaña al grupo hasta Iktan.', 'Nombre Zoltan coordinado con su presentación del bloque inicial. El apodo Chispitas y las variantes Soltan o Zoltán no crean identidades distintas; no se infiere un linaje o patrón mágico.'),
    history('Angelique', 'personaje', 'El huésped de las chispas', 'La encargada felina de la taberna de Iktan se presenta a Zoltan como Angelic y le ofrece una cerveza, compañía y una habitación. Lo corteja junto a la barra mientras aparta a Sir Poncelot y termina llevándolo a un cuarto. La escena se cierra con ruidos y chispas, sin narrar consecuencias posteriores.', ['46-212', '46-221'], False, 'Encargada felina de la taberna de Iktan que corteja a Zoltan.', 'Continuidad con la persona cortejada antes por Coyote, conservando grafía provisional Angelique/Angelic. No se afirma un título real por su propuesta de que la llamen princesa ni se fusionan otras taberneras sin cotejo.'),
    history('Etley', 'personaje', 'La vuelta con Citlali', 'Etley aparece en el colegio con Leo y acude al silbido de Citlali. La profesora cuenta que dos compañeros lo llevaron y la invita a una reunión de madres. Citlali se lo lleva y trata de enseñarle que no imite las palabrotas. La cría, con gorro y mochila escolares, se distrae con una mariposa y no demuestra entender la educación que recibe.', ['46-209', '46-210', '46-211', '46-216', '46-219']),
    history('Leo', 'personaje', 'Las amenazas a la profesora', 'Leo sale del colegio con Etley y vuelve a desafiar a la profesora. Ante sus insultos, Citlali lo golpea con la alpargata y le exige que modere el lenguaje. El niño protesta diciendo que Naór es su madre y la princesa de Atlan; después sale llorando a buscarla. La sesión no muestra ese encuentro ni una reprimenda posterior de Tesara.', ['46-209', '46-210', '46-211']),
    history('Miausi', 'personaje', 'La profesora y las reuniones de madres', 'Miausi sale del colegio con las gafas puestas cuando Leo vuelve a desobedecerla. Explica a Citlali que el niño intenta influir también en Etley y la invita a la reunión dominical de madres. Advierte del lenguaje de la princesa de Atlan y presencia la reprimenda de Citlali antes de regresar a clase.', ['46-209', '46-210', '46-211'], True, 'Profesora de Iktan, de nombre Miausi, que atiende a Leo y a Etley y convoca a Citlali a la reunión de madres.', 'Identidad provisional de la presentación repetida en este capítulo. No se la fusiona automáticamente con la Directora del colegio de Iktan del capítulo 45.'),
    history('Froger', 'personaje', 'Veinticuatro monedas por el collar', 'Froger es un alquimista con aspecto de sapo al que Ione encuentra buscando un comprador para su joya. Examina el collar y ofrece veinticinco monedas; ella pide una más, pero él baja a veinticuatro y cierra la venta por ese importe.', ['46-217', '46-218'], True, 'Alquimista de Iktan con aspecto de sapo que compra un collar a Ione.', 'Grafía Froger procedente del nombramiento del director. Se distingue de Parroter, alquimista kenku de Cuicapalli, y no se le identifica con un herrero por la búsqueda inicial de Ione.'),
    history('Novato ausente de Ione', 'personaje', 'El tripulante que no llega a Iktan', 'Al comprobar a su gente en la taberna, Ione echa de menos al novato. Los compañeros lo llaman Jacki y no saben qué le ha ocurrido; los trillizos solo afirman que ya faltaba al abandonar la playa. Ione teme que se haya perdido y quiere averiguar si ha vuelto hacia Shiaru. La sesión no muestra dónde está.', ['46-214', '46-215'], True, 'Tripulante ausente al que el grupo llama novato y Jacki cuando Ione se reúne con los suyos.', 'Ficha descriptiva provisional de la mención, sin imponer identidad con Jack veterano o el joven Jackie referido por Taylor. Las conjeturas de muerte o tiburones no se convierten en desenlace.'),
    history('Tripulación del Zampaolas', 'faccion', 'Cuatro días esperando a la capitana', 'Los tripulantes que han llegado a Iktan se acomodan en la taberna, juegan a cartas y alquilan habitaciones compartidas. Dicen a Ione que llevan cuatro días allí, pero falta el novato y nadie confirma su destino. La capitana propone vender una joya y reunir apoyos para recuperar Shiaru; recuerda que Bonnie ya no está y les promete protección.', ['46-205', '46-208', '46-214', '46-215']),
    history('Baps', 'personaje', 'Las habitaciones de Iktan', 'Baps está entre los tripulantes que Ione encuentra bebiendo y jugando a cartas en Iktan. Confirma que han alquilado habitaciones, aunque están llenas y se comparten. La reunión con la capitana revela que el novato sigue ausente, sin que las especulaciones de sus compañeros permitan localizarlo.', ['46-208', '46-214']),
    history('Mugre', 'personaje', 'La espera en la taberna', 'Mugre aparece junto a Baps, Ojo Ausente y los trillizos en la taberna de Iktan, ya acomodado entre cartas y cerveza. Ione llega y pregunta por el estado de sus hombres. La sesión no individualiza para Mugre una explicación del viaje ni del paradero del novato.', ['46-208']),
    history('Ojo Ausente', 'personaje', 'El reencuentro con Ione', 'Ojo Ausente está entre quienes esperan en la taberna de Iktan cuando llega Ione. La escena muestra al grupo jugando y bebiendo, sin atribuirle por separado las conjeturas sobre el novato que falta.', ['46-208']),
    history('Erandy', 'personaje', 'Eleanor vuelve a encontrarla', 'Erandy está en la barra de Iktan con los otros compañeros cuando llega Eleanor. Esta se concentra en comprobar cómo está y se reúne con ella. El tramo no representa una curación del agotamiento anterior ni reproduce una conversación extensa de la escudera.', ['46-208', '46-213']),
    history('Ilikar', 'personaje', 'Con Cipo en Iktan', 'Ilikar aparece en la taberna de Iktan, junto a Erandy, Lunaria y Sir Poncelot. El director lo muestra jugando con Cipo cuando Eleanor vuelve a reunirse con los compañeros.', ['46-208', '46-213']),
    history('Cipo', 'personaje', 'El juego junto a Ilikar', 'Cipo está con Ilikar en la taberna de Iktan cuando Eleanor llega y comprueba el estado de Erandy. La escena no le asigna un combate nuevo ni un poder distinto.', ['46-213']),
    history('Lunaria', 'personaje', 'En la taberna antes del reencuentro', 'Lunaria está en la barra de Iktan al llegar el grupo perdido. El director imagina que intenta quemar algún madero y advierte a Eleanor que no se dejaría coger en brazos, sin representar un incendio nuevo consumado.', ['46-208', '46-213']),
    history('Sir Poncelot', 'personaje', 'La barra de Iktan', 'Sir Poncelot está entre los compañeros que Ione y Eleanor encuentran en la taberna de Iktan. Angelique lo aparta de la barra para sentarse a beber y cortejar a Zoltan.', ['46-208', '46-212']),
    history('Iktan', 'lugar', 'El destino recuperado', 'Citlali reconoce los senderos y guía a sus compañeros hasta Iktan después de perder el camino. La llegada reúne al grupo con la tripulación que espera en la taberna. En el colegio, Citlali recupera a Etley y recibe una invitación de Miausi. En las tiendas, Ione vende un collar a Froger y Eleanor se desprende de lo que llevaba. La visita propuesta a Walulu queda por hacer.', ['46-207', '46-208', '46-209', '46-210', '46-216', '46-218', '46-220']),
    history('El Huevo Emplumado', 'lugar', 'Los compañeros que ya esperaban', 'La taberna de Iktan acoge a los tripulantes y compañeros que esperaban a Ione. Han alquilado habitaciones compartidas y se acomodan entre cartas y cerveza. Eleanor se reúne con Erandy; Ione descubre la ausencia del novato y prepara sus planes de recaudar recursos. Angelique atiende y corteja a Zoltan antes de llevarlo a una habitación.', ['46-208', '46-212', '46-213', '46-214', '46-215', '46-221']),
    history('Colegio de Iktan', 'lugar', 'Etley y la cita del domingo', 'Citlali encuentra a Etley con Leo a la salida del colegio. Miausi se queja del comportamiento de Leo, explica cómo llegó la cría e invita a su cuidadora a las reuniones dominicales. Tras la reprimenda de Citlali, Leo corre a buscar a su madre y ella se lleva a Etley, que aún lleva el gorro y la mochila.', ['46-209', '46-210', '46-211', '46-219']),
    history('Collar hallado por Ione en la aldea caníbal', 'objeto', 'La venta a Froger', 'Ione busca un comprador para el collar hallado durante la expedición y lo ofrece a Froger al llegar a Iktan. El alquimista propone veinticinco monedas; tras pedir ella veintiséis y recibir una contraoferta menor, termina vendido por veinticuatro.', ['46-217', '46-218'], True, 'Collar de oro y joyas que Ione lleva a Iktan y vende para reunir recursos.', 'Origen del hallazgo coordinado con el bloque anterior. Se mantiene separado del collar de Blink y del collar antiguo de la misión de Bonnie; no se le atribuyen poderes mágicos.'),
    history('Tiranosaurios de la aldea caníbal', 'personaje', 'La muerte y el colmillo frustrado', 'Tras los rayos que derriban a uno de los dos animales, Citlali drena al que queda y ambos terminan muertos. Eleanor corta un trozo de carne sin herramientas adecuadas. Zoltan pretende extraer un colmillo con su electricidad, pero chamusca el cadáver y rompe los dientes, sin conseguir un trofeo intacto.', ['46-201', '46-202', '46-204'], True, 'Dos tiranosaurios que atacan al grupo en la aldea abandonada y son derrotados.', 'Ficha colectiva coordinada con el combate del bloque anterior. No se fijan sexo, nombres personales ni una identidad con la cría Etley.'),
    history('Shiaru', 'lugar', 'El regreso que Ione quiere preparar', 'Desde Iktan, Ione anuncia que quiere recuperar Shiaru y reunir gente nueva para su causa. También espera averiguar si el novato ausente ha vuelto por allí. La sesión muestra una venta para conseguir recursos, pero no la expedición, el estado actual del pueblo o un cambio de gobierno comprobado.', ['46-215', '46-218']),
]

